(() => { const a = window.__CITY_APP, C = window.CITY; a.cameraSystem.cinema = null; a.selectMode('person'); a.selectCamera('chase', true);
 const r = C.DECK_RUNS.find((d) => /^Bloor Street/.test(d.name) && Math.min(d.pts[0].x, d.pts[d.pts.length - 1].x) < 2240 && Math.max(d.pts[0].x, d.pts[d.pts.length - 1].x) > 2240 && d.pts.every((p) => Math.abs(p.z + 2800) < 30));
 let p = null, q = null; for (let i = 0; i + 1 < r.pts.length; i++) { const u = r.pts[i], v = r.pts[i + 1]; if (!p || Math.hypot(v.x - u.x, v.z - u.z) > Math.hypot(q.x - p.x, q.z - p.z)) { p = u; q = v; } }
 if (q.x < p.x) [p, q] = [q, p];
 const L = Math.hypot(q.x - p.x, q.z - p.z), ux = (q.x - p.x) / L, uz = (q.z - p.z) / L;
 const x = p.x + ux * 5 - uz * 2, z = p.z + uz * 5 + ux * 2, y = C.deckHeightAt(x, z, 1, 1);
 a.teleportTo(x, z, Math.atan2(ux, uz), y); return { start: [+x.toFixed(1), +z.toFixed(1)], y, heading: +Math.atan2(ux, uz).toFixed(3), end: [+q.x.toFixed(1), +q.z.toFixed(1)], length: +L.toFixed(0) }; })()

